input.new_string:
if weight_kg <= 0:
    raise ValueError("weight must be positive")
max_weight = WEIGHT_TIERS[-1][0]
if weight_kg > max_weight:
    raise ValueError(f"weight must be at most {max_weight} kg")
if zone not in ZONE_SURCHARGE_PCT:
    raise ValueError(f"unknown zone: {zone}")
for limit, charge in WEIGHT_TIERS:
    if weight_kg <= limit:
        base = charge
        break
# Integer arithmetic keeps the half-up rounding exact (no float drift).
total_hundredths = base * (100 + ZONE_SURCHARGE_PCT[zone])
return (total_hundredths + 50) // 100
